import{n as sha256Hex}from"./node-crypto-DPk8agfR.mjs";import{r as sha256File}from"./crypto-digest-T8X5EZni.mjs";import path from"node:path";import fs from"node:fs/promises";import{root}from"@openclaw/fs-safe/root";
//!src/skills/lifecycle/skill-tree-digest.ts
const EXCLUDED_METADATA_DIRS=/* @__PURE__ */ new Set([`.clawhub`,`.clawdhub`]);async function digestClawHubSkillTree(e){const t=await root(e);const n=[];for await(const r of t.walk(``,{symlinkPolicy:`include`,entryFilter:({relativePath:e})=>EXCLUDED_METADATA_DIRS.has(e)?`skip-subtree`:`include`})){const t=r.relativePath;const i=await fs.lstat(path.join(e,t));if(i.isSymbolicLink()||!i.isDirectory()&&!i.isFile())throw new Error(`Skill tree contains unsupported entry ${JSON.stringify(t)}.`);if(i.isDirectory()){n.push({path:t,type:`directory`});continue}if(i.nlink>1)throw new Error(`Skill tree contains hard-linked file ${JSON.stringify(t)}.`);const a=i.size>0?i.size-1:void 0;n.push({path:t,type:`file`,sha256:await sha256File(path.join(e,t),a)})}return`sha256:${sha256Hex(JSON.stringify(n))}`}async function checkClawHubSkillPlanAtPath(e,t){try{const n=await fs.lstat(t);if(!n.isDirectory()||n.isSymbolicLink())return{ok:false,error:`Skill ${JSON.stringify(e.slug)} changed during update.`};const r=await fs.readFile(path.join(t,e.skillFilePath));if(sha256Hex(r)!==e.skillFileSha256||await digestClawHubSkillTree(t)!==e.fileTreeSha256)return{ok:false,error:`Skill ${JSON.stringify(e.slug)} changed during update.`};return{ok:true}}catch(e){return{ok:false,error:String(e)}}}export{digestClawHubSkillTree as n,checkClawHubSkillPlanAtPath as t};